import { Router, type Request, type Response } from 'express';

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  if (typeof data !== 'object' || data === null) {
    return false;
  }
  const candidate = data as Record<string, unknown>;
  if (typeof candidate.url !== 'string') {
    return false;
  }
  if (candidate.title !== undefined && typeof candidate.title !== 'string') {
    return false;
  }
  if (candidate.tags !== undefined) {
    if (!Array.isArray(candidate.tags)) {
      return false;
    }
    if (!candidate.tags.every((tag: unknown): tag is string => typeof tag === 'string')) {
      return false;
    }
  }
  return true;
}

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response) => {
  const body: unknown = req.body;
  if (!isCreateBookmarkInput(body)) {
    res.status(400).json({ error: 'Invalid bookmark payload' });
    return;
  }

  res.status(201).json({
    url: body.url,
    title: body.title,
    tags: body.tags,
  });
});

