import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create a bookmark with id, createdAt, and input properties', () => {
      const input = {
        url: 'https://example.com/guide',
        title: 'Example Guide',
        tags: ['guide', 'test'],
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id.length).toBeGreaterThan(0);
      expect(bookmark.url).toBe(input.url);
      expect(bookmark.title).toBe(input.title);
      expect(bookmark.tags).toEqual(input.tags);
      expect(bookmark.createdAt).toBeDefined();
      expect(Number.isNaN(Date.parse(bookmark.createdAt))).toBe(false);
    });

    it('should create a bookmark without optional fields', () => {
      const input = {
        url: 'https://example.com/minimal',
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(bookmark.url).toBe(input.url);
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating a bookmark with an existing URL', () => {
      const url = 'https://example.com/duplicate';
      service.create({ url, title: 'First' });

      expect(() => {
        service.create({ url, title: 'Second' });
      }).toThrow(DuplicateBookmarkError);
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by id', () => {
      const created = service.create({
        url: 'https://example.com/item',
        title: 'Item',
      });

      const retrieved = service.getById(created.id);
      expect(retrieved).toEqual(created);
    });

    it('should return undefined when retrieving a non-existent id', () => {
      const result = service.getById('non-existent-id');
      expect(result).toBeUndefined();
    });

    it('should retrieve all bookmarks sorted by createdAt descending', async () => {
      const first = service.create({ url: 'https://example.com/first' });
      await new Promise<void>((resolve) => setTimeout(resolve, 5));
      const second = service.create({ url: 'https://example.com/second' });

      const all = service.getAll();
      expect(all.length).toBe(2);
      expect(all[0].id).toBe(second.id);
      expect(all[1].id).toBe(first.id);
    });
  });
});

